// Checks a model's codec data for a genuine Hi-Res-capable codec (LDAC or
// any aptX variant). `codecs` (array) is the primary field; `codec` (a
// comma-separated summary string) is the fallback for older/simpler entries.
const HIRES_CODEC_MATCHES = ['ldac', 'aptx'];
function hasHiResCodec(m) {
  const list = Array.isArray(m.codecs) && m.codecs.length
    ? m.codecs
    : (typeof m.codec === 'string' ? m.codec.split(',').map((c) => c.trim()) : []);
  return list.some((c) => HIRES_CODEC_MATCHES.some((h) => String(c).toLowerCase().includes(h)));
}

// Detects an aptX Low Latency-class codec — the signal that actually matters
// for lip-sync when watching video over Bluetooth (plain aptX/LDAC do not
// guarantee low latency by themselves).
function hasLowLatencyCodec(m) {
  const list = Array.isArray(m.codecs) && m.codecs.length
    ? m.codecs
    : (typeof m.codec === 'string' ? m.codec.split(',').map((c) => c.trim()) : []);
  return list.some((c) => String(c).toLowerCase().includes('low latency') || String(c).toLowerCase().includes('ll'));
}

// `type` is a free-text optional DATA V1 field (see schema.sql) — not every
// row has it populated, so this is a best-effort substring match rather than
// an exact enum check.
function isOpenEarType(m) {
  return String(m.type || '').toLowerCase().includes('open');
}

